sql_query:
SELECT "Secondary endpoint"
FROM clinical_trials
WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Secondary endpoint" AS source_value FROM clinical_trials WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_irae_assessed(source_value) AS "irAE_assessed"
FROM base;
